DELIMITER $$

CREATE TRIGGER trg_actualizar_fecha_alumno
BEFORE UPDATE ON alumnos
FOR EACH ROW
BEGIN
  SET NEW.fecha_ultima_actualizacion = NOW();
END $$

DELIMITER ;

DELIMITER $$

CREATE PROCEDURE sp_inscribir_alumno_comision (
  IN p_id_alumno INT,
  IN p_id_comision INT
)
BEGIN
  INSERT INTO inscripcion_alumno_comision (id_alumno, id_comision, fecha_inscripcion, estado)
  VALUES (p_id_alumno, p_id_comision, CURDATE(), 'Cursa');
END $$

DELIMITER ;

DELIMITER $$

CREATE FUNCTION fn_promedio_alumno (p_id_alumno INT)
RETURNS DECIMAL(4,2)
DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE v_promedio DECIMAL(4,2);

  SELECT AVG(nota) INTO v_promedio
  FROM notas
  WHERE id_alumno = p_id_alumno;

  RETURN IFNULL(v_promedio, 0);
END $$

DELIMITER ;

explanation:
Cada objeto resuelve una parte distinta:

- el **CHECK** valida el dominio del dato;
- el **trigger** calcula un campo derivado;
- el **procedure** ofrece una operación reutilizable.

Orden de ejecución en un INSERT: primero corren los triggers BEFORE (que pueden cambiar `NEW`) y después se validan las restricciones sobre la fila final. Por eso, si un trigger "arreglara" una nota inválida, el CHECK ya no la rechazaría.

