DELIMITER $$

CREATE FUNCTION fn_cantidad_alumnos_activos_carrera (p_id_carrera INT)
RETURNS INT
DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE v_cantidad INT;
  SELECT COUNT(*) INTO v_cantidad
  FROM alumno_carrera
  WHERE id_carrera = p_id_carrera AND estado = 'activa';
  RETURN v_cantidad;
END $$

CREATE FUNCTION fn_clasificar_demanda_carrera (p_id_carrera INT)
RETURNS VARCHAR(20)
DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE v_cantidad INT;
  SET v_cantidad = fn_cantidad_alumnos_activos_carrera(p_id_carrera);

  IF v_cantidad < 20 THEN
    RETURN 'baja demanda';
  ELSEIF v_cantidad <= 70 THEN
    RETURN 'demanda media';
  ELSE
    RETURN 'alta demanda';
  END IF;
END $$

DELIMITER ;
